-- 0117_stock_problems: «Асуудалтай бараа» (ADR-0230): a warehouse's fixed party and expense type,
-- what took a product off a warehouse's problem list, and the morning sheets with their counts.
-- New tables only (ADR-0206). Generated by drizzle-kit; added by hand: the REVOKE at the end
-- (a decision and a count are kept; nothing here is deleted).
CREATE TABLE "stock_problem_resolutions" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "stock_problem_resolutions_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"warehouse_id" bigint NOT NULL,
	"product_id" bigint NOT NULL,
	"kind" text NOT NULL,
	"status" text NOT NULL,
	"covers_until" timestamp with time zone DEFAULT now() NOT NULL,
	"qty_base" numeric(14, 3),
	"on_hand" numeric(14, 3),
	"note" text,
	"issue_id" bigint,
	"adjustment_id" bigint,
	"sheet_id" bigint,
	"pos_resolved_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" bigint,
	"closed_at" timestamp with time zone,
	CONSTRAINT "stock_problem_resolutions_kind" CHECK ("stock_problem_resolutions"."kind" IN ('LEGIT', 'ZERO_OUT', 'COUNT')),
	CONSTRAINT "stock_problem_resolutions_status" CHECK ("stock_problem_resolutions"."status" IN ('PENDING', 'DONE', 'CANCELLED')),
	CONSTRAINT "stock_problem_resolutions_closed" CHECK (("stock_problem_resolutions"."status" = 'PENDING') = ("stock_problem_resolutions"."closed_at" IS NULL)),
	CONSTRAINT "stock_problem_resolutions_pending_doc" CHECK ("stock_problem_resolutions"."status" <> 'PENDING' OR "stock_problem_resolutions"."issue_id" IS NOT NULL OR "stock_problem_resolutions"."adjustment_id" IS NOT NULL),
	CONSTRAINT "stock_problem_resolutions_qty" CHECK ("stock_problem_resolutions"."qty_base" IS NULL OR "stock_problem_resolutions"."qty_base" > 0),
	CONSTRAINT "stock_problem_resolutions_note" CHECK ("stock_problem_resolutions"."note" IS NULL OR length("stock_problem_resolutions"."note") BETWEEN 1 AND 300)
);
--> statement-breakpoint
CREATE TABLE "stock_problem_settings" (
	"warehouse_id" bigint PRIMARY KEY NOT NULL,
	"customer_id" bigint,
	"expense_type_id" bigint,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_by" bigint
);
--> statement-breakpoint
CREATE TABLE "stock_problem_sheet_lines" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "stock_problem_sheet_lines_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"sheet_id" bigint NOT NULL,
	"product_id" bigint NOT NULL,
	"system_qty" numeric(14, 3) NOT NULL,
	"red_qty" numeric(14, 3) NOT NULL,
	"cut_qty" numeric(14, 3) NOT NULL,
	"counted_qty" numeric(14, 3),
	"on_hand_at_count" numeric(14, 3),
	"difference" numeric(14, 3),
	"counted_at" timestamp with time zone,
	"counted_by" bigint,
	"outcome" text,
	"resolution_id" bigint,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "stock_problem_sheet_lines_product" UNIQUE("sheet_id","product_id"),
	CONSTRAINT "stock_problem_sheet_lines_count" CHECK (("stock_problem_sheet_lines"."counted_qty" IS NULL) = ("stock_problem_sheet_lines"."on_hand_at_count" IS NULL) AND ("stock_problem_sheet_lines"."counted_qty" IS NULL) = ("stock_problem_sheet_lines"."difference" IS NULL) AND ("stock_problem_sheet_lines"."counted_qty" IS NULL) = ("stock_problem_sheet_lines"."counted_at" IS NULL) AND ("stock_problem_sheet_lines"."counted_qty" IS NULL OR ("stock_problem_sheet_lines"."counted_qty" >= 0 AND "stock_problem_sheet_lines"."difference" = "stock_problem_sheet_lines"."counted_qty" - "stock_problem_sheet_lines"."on_hand_at_count"))),
	CONSTRAINT "stock_problem_sheet_lines_outcome" CHECK ("stock_problem_sheet_lines"."outcome" IS NULL OR ("stock_problem_sheet_lines"."outcome" IN ('EQUAL', 'SHORTAGE', 'SURPLUS') AND "stock_problem_sheet_lines"."counted_qty" IS NOT NULL))
);
--> statement-breakpoint
CREATE TABLE "stock_problem_sheets" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "stock_problem_sheets_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"warehouse_id" bigint NOT NULL,
	"sheet_date" date NOT NULL,
	"status" text DEFAULT 'OPEN' NOT NULL,
	"built_at" timestamp with time zone DEFAULT now() NOT NULL,
	"built_by" bigint,
	"approved_at" timestamp with time zone,
	"approved_by" bigint,
	"issue_id" bigint,
	"adjustment_id" bigint,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "stock_problem_sheets_day" UNIQUE("warehouse_id","sheet_date"),
	CONSTRAINT "stock_problem_sheets_status" CHECK ("stock_problem_sheets"."status" IN ('OPEN', 'APPROVED', 'CLOSED')),
	CONSTRAINT "stock_problem_sheets_approved" CHECK (("stock_problem_sheets"."status" = 'APPROVED') = ("stock_problem_sheets"."approved_at" IS NOT NULL) AND ("stock_problem_sheets"."approved_at" IS NULL) = ("stock_problem_sheets"."approved_by" IS NULL))
);
